import previous from "./fixtures/pre-radix-revisions.json";
import type { Bundle, Question, Template, SetRecord } from "../src/core/types";
import { restorePreFlow } from "./flow-history";

// Restore the released distribution before adding this optional lesson. The
// snapshot is fixed input, never regenerated by the tests or manifest updater.
export function restorePreRadix(bundle: Bundle) {
  restorePreFlow(bundle);
  for (const [id, q] of Object.entries(previous.questions))
    bundle.questions[bundle.questions.findIndex(q => q.id === id)] = structuredClone(q) as Question;
  bundle.templates[bundle.templates.findIndex(t => t.id === previous.template.id)] = structuredClone(previous.template) as Template;
  for (const [id, set] of Object.entries(previous.sets))
    bundle.sets[bundle.sets.findIndex(s => s.id === id)] = structuredClone(set) as SetRecord;
  bundle.catalog.revision = previous.catalogRevision;
  return bundle;
}
